#!/usr/bin/env node
/* Backfill SEO/LLM metadata into the already-published report and sector HTML
 * files: meta description, canonical link, Open Graph tags, and Article
 * JSON-LD — derived from data/reports.json and data/sectors.json, which
 * already carry a headline/description-worthy field for every entry.
 *
 * These files are generated by other projects' renderers (market-data,
 * rajan-sector-analysis) which don't emit this metadata today — this script
 * only patches the copies already sitting in this repo. Idempotent: skips
 * any file that already has a <meta name="description">, so re-running is
 * safe and running it after the upstream renderer is fixed is a no-op.
 *
 *   node scripts/inject-page-meta.mjs
 */
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { resolve, join } from 'node:path';

const ROOT = resolve(new URL('..', import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, '$1'));
const SITE = 'https://rajan1973.github.io';

const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const escJson = (s) => JSON.stringify(String(s));

function alreadyTagged(html) {
  return /<meta[^>]+name=["']description["']/i.test(html);
}

function titleOf(html) {
  const m = html.match(/<title>([\s\S]*?)<\/title>/i);
  return m ? m[1].replace(/\s+/g, ' ').trim() : '';
}

function inject(html, { description, url, title, type, datePublished, keywords }) {
  const block = [
    `<meta name="description" content="${esc(description)}">`,
    `<link rel="canonical" href="${esc(url)}">`,
    `<meta property="og:type" content="${type === 'Article' || type === 'NewsArticle' ? 'article' : 'website'}">`,
    `<meta property="og:site_name" content="NIFTY &amp; BEYOND">`,
    `<meta property="og:title" content="${esc(title)}">`,
    `<meta property="og:description" content="${esc(description)}">`,
    `<meta property="og:url" content="${esc(url)}">`,
    `<meta property="og:image" content="${SITE}/assets/logo.webp">`,
    `<meta name="twitter:card" content="summary">`,
    `<meta name="twitter:title" content="${esc(title)}">`,
    `<meta name="twitter:description" content="${esc(description)}">`,
    keywords ? `<meta name="keywords" content="${esc(keywords)}">` : null,
    `<meta name="robots" content="index,follow">`,
    `<script type="application/ld+json">`,
    JSON.stringify({
      '@context': 'https://schema.org',
      '@type': type,
      headline: title,
      description,
      url,
      ...(datePublished ? { datePublished } : {}),
      isPartOf: { '@type': 'WebSite', name: 'NIFTY & BEYOND', url: SITE + '/' },
      publisher: { '@type': 'Organization', name: 'NIFTY & BEYOND', url: SITE + '/', logo: SITE + '/assets/logo.webp' },
    }, null, 2),
    `</script>`,
  ].filter(Boolean).join('\n');

  return html.replace(/<\/title>/i, '</title>\n' + block);
}

function run() {
  let patched = 0, skipped = 0, missing = 0;

  const reportsManifest = JSON.parse(readFileSync(join(ROOT, 'data/reports.json'), 'utf8'));
  for (const r of reportsManifest.reports || []) {
    const f = join(ROOT, r.path);
    if (!existsSync(f)) { missing++; continue; }
    const html = readFileSync(f, 'utf8');
    if (alreadyTagged(html)) { skipped++; continue; }
    const description = `${r.headline} — ${(r.tags || []).slice(0, 4).join(' · ')}`.slice(0, 300);
    const out = inject(html, {
      description,
      url: `${SITE}/${r.path}`,
      title: titleOf(html) || r.headline,
      type: 'NewsArticle',
      datePublished: r.id.slice(0, 10),
      keywords: ['NIFTY', 'Sensex', 'Indian stock market', ...(r.mentions || []).slice(0, 8)].join(', '),
    });
    writeFileSync(f, out);
    patched++;
    console.log('  patched report ' + r.path);
  }

  const sectorsManifest = JSON.parse(readFileSync(join(ROOT, 'data/sectors.json'), 'utf8'));
  for (const s of sectorsManifest.sectors || []) {
    if (s.status !== 'published' || !s.path) continue;
    const f = join(ROOT, s.path);
    if (!existsSync(f)) { missing++; continue; }
    const html = readFileSync(f, 'utf8');
    if (alreadyTagged(html)) { skipped++; continue; }
    const description = `${s.name} ${s.quarter || ''} sector earnings review — ${s.note || ''}`.trim().slice(0, 300);
    const out = inject(html, {
      description,
      url: `${SITE}/${s.path}`,
      title: titleOf(html) || s.title || s.name,
      type: 'Article',
      keywords: [s.name, 'sector earnings review', 'Indian equities', ...(s.covers || []).slice(0, 8)].join(', '),
    });
    writeFileSync(f, out);
    patched++;
    console.log('  patched sector ' + s.path);
  }

  console.log(`\n${patched} file(s) patched, ${skipped} already had metadata, ${missing} referenced file(s) not found.`);
}

run();
